function manual(){ensureTopControls();const persisted=loadUiState(),p=$('#manualPanel'),isAdmin=panelKind==='ADMIN',state=isAdmin?adminDraft:(customDraft||persisted),domain=(label,key,order)=>{const chosen=order.filter(x=>state[key]?.includes(x)&&sourceEligibility(x,key).eligible),weight=chosen.length?Math.round(1000/chosen.length)/10:0;return `<div class="manual-domain"><b>${label}</b>${order.map(x=>{const s=sourceEligibility(x,key),on=chosen.includes(x);return `<label class="manual-source ${s.eligible?'':'disabled'}"><input data-domain="${key}" value="${x}" type="checkbox" ${on?'checked':''} ${s.eligible?'':'disabled'}><span>${names[x]}<small>${s.state}</small></span><em>${on?weight+'%':'—'}</em></label>`}).join('')}</div>`};$('#autoBtn').classList.toggle('active',persisted.mode==='AUTO');$('#manualBtn').classList.toggle('active',persisted.mode==='CUSTOM');$('#autoBtn').onclick=()=>{uiModelState=defaultUiState();saveUiState();dismissManual();renderAll()};if($('#adminManualBtn'))$('#adminManualBtn').classList.toggle('active',isAdmin);if(p.hidden){$('#manualBtn').onclick=openCustom;if($('#adminManualBtn'))$('#adminManualBtn').onclick=openAdmin;return}p.innerHTML=`<div class="manual-panel-head"><b>${isAdmin?'ADMIN PRODUCTION':'CUSTOM'} SOURCES</b><button id="closeManualBtn" type="button" aria-label="Close source controls">×</button></div><div class="manual-grid">${domain('SPREAD','spread',spreadOrder)}${domain('TOTAL','total',totalOrder)}</div><div class="manual-actions">Selected valid sources are equal-weighted per game · ${isAdmin?'AUTHENTICATED PRODUCTION WRITE':'THIS DEVICE ONLY · NO ACCOUNT OR SERVER WRITE'}</div><div class="manual-buttons"><button id="${isAdmin?'adminSaveManualBtn':'applyCustomBtn'}" class="wr-btn">${isAdmin?'SAVE ADMIN MANUAL':'APPLY CUSTOM'}</button><button id="${isAdmin?'adminRestoreAutoBtn':'resetCustomBtn'}" class="wr-btn">${isAdmin?'RESTORE PRODUCTION AUTO':'RESET TO AUTO'}</button></div>`;p.querySelectorAll('input').forEach(x=>x.onchange=()=>{state[x.dataset.domain]=[...p.querySelectorAll(`[data-domain="${x.dataset.domain}"]:checked`)].map(n=>n.value);if(isAdmin)adminDraft=state;else customDraft=state;manual()});$('#closeManualBtn').onclick=dismissManual;$('#manualBtn').onclick=()=>panelKind==='CUSTOM'&&!p.hidden?dismissManual():openCustom();if($('#adminManualBtn'))$('#adminManualBtn').onclick=()=>panelKind==='ADMIN'&&!p.hidden?dismissManual():openAdmin();if($('#applyCustomBtn'))$('#applyCustomBtn').onclick=()=>{uiModelState={...customDraft,schema_version:1,mode:'CUSTOM'};saveUiState();dismissManual();renderAll()};if($('#resetCustomBtn'))$('#resetCustomBtn').onclick=()=>{uiModelState=defaultUiState();saveUiState();dismissManual();renderAll()}}
function recordText(r){return `${r.wins}-${r.losses}${r.pushes?'-'+r.pushes:''}`}
function teamActivityCard(t){if(!t)return '<div class="activity-card">Team activity unavailable.</div>';const rows=t.schedule.map(x=>`<div class="team-schedule-row ${x.completed?'final':''}"><div><b>${human(x.date)}</b><small>${x.site==='HOME'?'vs':x.site==='AWAY'?'at':'vs · N'} ${esc(x.opponent.name)}</small></div><div class="schedule-result">${x.completed?`<strong>${x.su_result} ${x.team_score}-${x.opponent_score}</strong><small>ATS ${x.ats_result||'—'} · O/U ${x.ou_result||'—'}</small>`:`<strong>${tipLabel({tip:x.tip,tip_tbd:String(x.status_detail||'').toUpperCase().includes('TBD')})}</strong><small>ATS — · O/U —</small>`}</div></div>`).join('');return `<section class="team-activity-card"><div class="team-activity-head">${metricLogo(t)}<div><b>${esc(t.display_name)}</b><span>2026–27 · ${esc(t.conference||'Independent')}${t.rank?' · #'+t.rank:''}</span></div></div><div class="team-records"><div><small>SU</small><b>${t.record.su.wins}-${t.record.su.losses}</b></div><div><small>ATS</small><b>${recordText(t.record.ats)}</b></div><div><small>O/U</small><b>${t.record.ou.overs}-${t.record.ou.unders}${t.record.ou.pushes?'-'+t.record.ou.pushes:''}</b></div></div><div class="team-schedule">${rows||'<p>No canonical schedule rows.</p>'}</div></section>`}
function teamActivity(g){const all=DATA.team_activity?.teams||[],byId=id=>all.find(x=>x.team_id===id);if(!g)return '<div class="activity-card">Select a matchup.</div>';return `<div class="matchup-activity-title">${esc(g.away.name)} at ${esc(g.home.name)}</div>${teamActivityCard(byId(g.away.team_id))}${teamActivityCard(byId(g.home.team_id))}<div class="schedule-note">${DATA.team_activity.completed_games} completed games · stored-close authority: PINN → DK → FD → MGM → CZR</div>`}
function fmtEt(v){return v?new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',month:'numeric',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(v)):'—'}
function marketOpeners(g){const o=g.market?.market_openers||{},line=(q,k)=>q?`${k==='spread'?esc(q.selection||q.side)+' ':''}${quoteLine(q,k)} ${americanPrice(q.price)}`:'OPENING LINE NOT CAPTURED';return `<section class="market-activity-section"><b>OPENERS</b><div class="market-opener"><span>SPREAD</span><strong>${line(o.spread,'spread')}</strong></div><div class="market-opener"><span>TOTAL</span><strong>${line(o.total,'total')}</strong></div></section>`}
function marketMove(g){const m=g.market_activity?.most_recent_move;if(!m)return `<section class="market-activity-section"><b>MOST RECENT MOVE</b><div class="market-empty">NO MATERIAL MOVE CAPTURED</div></section>`;const before={...m.previous,side:m.side},after={...m.current,side:m.side},selection=m.current?.selection?`${esc(m.current.selection)} · `:'';return `<section class="market-activity-section"><b>MOST RECENT MOVE</b><div class="market-move"><time>${fmtEt(m.observed_at)}</time><strong>${bookAbbr(m)} · ${short(m.market_type).toUpperCase()}</strong><span>${selection}${quoteLine(before,m.market_type)} ${americanPrice(before.price)} → ${quoteLine(after,m.market_type)} ${americanPrice(after.price)}</span></div></section>`}
function currentByBook(g){const grouped={};(g.market?.latest||[]).filter(x=>x.provider_type!=='EXCHANGE').forEach(q=>{const k=q.provider_key||q.provider_name;(grouped[k]||(grouped[k]={name:q.provider_name,key:q.provider_key,rows:[]})).rows.push(q)});const cards=Object.values(grouped).map(book=>{const spread=book.rows.filter(x=>x.market_type==='spread').sort((a,b)=>Number(a.line)-Number(b.line))[0],total=book.rows.find(x=>x.market_type==='total'&&x.side==='OVER')||book.rows.find(x=>x.market_type==='total'),stamp=book.rows.map(x=>x.provider_updated_at||x.api_updated_at||x.acquired_at).filter(Boolean).sort().pop(),sq=spread?`${esc(spread.selection||spread.side)} ${compactSpreadLine(spread.line)} (${americanPrice(spread.price)})`:'—',tq=total?`${num(total.line)} (${americanPrice(total.price)})`:'—';return `<div class="market-book-card"><header><strong>${bookAbbr(book)}</strong><time>${fmtEt(stamp)}</time></header><div><b>SPREAD</b><span>${sq}</span></div><div><b>TOTAL</b><span>${tq}</span></div></div>`}).join('');return `<section class="market-activity-section"><b>CURRENT BY BOOK</b><div class="market-book-list">${cards||'<div class="market-empty">NO CURRENT SPORTSBOOK QUOTES</div>'}</div></section>`}
function marketActivity(g){if(!g)return '<div class="activity-card">Select a matchup.</div>';return `<div class="matchup-activity-title">${esc(g.away.name)} at ${esc(g.home.name)}</div>${marketOpeners(g)}${marketMove(g)}${currentByBook(g)}`}
function activity(){const o=DATA.operational_status||{},g=DATA.schedule.games.find(x=>x.game_id===activeGameId);$('#activityUpdated').textContent='UPDATED '+fmt(o.last_pipeline_run);document.querySelectorAll('[data-activity]').forEach(b=>b.classList.toggle('active',b.dataset.activity===activityTab));if(activityTab==='teams'){$('#activityList').innerHTML=teamActivity(g);return}if(activityTab==='market'){$('#activityList').innerHTML=marketActivity(g);return}if(!g){$('#activityList').innerHTML='<div class="activity-card">Select a matchup.</div>';return}const bodies={coaches:'<b>COACHES</b><p>No verified coach betting trends are published yet.</p>',postgame:`<b>POSTGAME</b><p>${g.status==='STATUS_FINAL'?'Final result available.':'No completed-game result yet.'}</p>`};$('#activityList').innerHTML=`<div class="activity-card">${bodies[activityTab]}</div>`}
async function startAction(action,payload={}){if(!DATA?.operator_controls_enabled||!operatorConnected){setOperatorState('OPERATOR LOGIN REQUIRED');return false}if(operatorTask)return false;try{if(action==='set_manual_sources'&&operatorContract?.supported_sources){for(const domain of ['spread','total']){const unsupported=(payload[`${domain}_sources`]||[]).filter(x=>!operatorContract.supported_sources[domain]?.includes(x));if(unsupported.length)throw Object.assign(Error(`Operator does not support ${domain} source ${unsupported[0]}`),{kind:'rejected'})}}opMessage(`${short(action)} · QUEUED`);const t=await opRequest('/tasks',{method:'POST',body:JSON.stringify({action,...payload})});await pollTask(t.task_id);setOperatorState('CONTROL READY');return true}catch(e){operatorTask=null;const msg=String(e?.message||e),auth=/load failed|failed to fetch|401|403|unauthor|forbidden/i.test(msg);setOperatorState(auth?'OPERATOR LOGIN REQUIRED':e?.kind==='task'?'TASK FAILED':e?.kind==='rejected'||/invalid|malformed|unsupported/i.test(msg)?'REQUEST REJECTED':'REQUEST FAILED');console.error('NCAAB operator action failed',{action,kind:e?.kind||'transport',status:e?.status||null,message:msg});return false}}
