function renderAll(){renderHealth();const state=loadUiState();if($('#persistenceState'))$('#persistenceState').textContent=state.mode==='CUSTOM'?'THIS DEVICE':'OFFICIAL';const label=$('.model-status-note>b');if(label)label.textContent=state.mode==='CUSTOM'?'CUSTOM MODEL':'AUTO MODEL';renderMatrix();activity()}
let ratingsSort={key:'composite_rank',direction:1},ratingsDetailTrigger=null;
const ratingColumns=['bart_torvik','haslametrics','evanmiya','kenpom','espn_bpi','teamrankings','dratings'];
function ratingStatus(s){return s==='CURRENT'||s==='UNCHANGED_BUT_CURRENT'?'CURRENT':s==='PRIOR_SEASON'?'PRIOR':s||'UNAVAILABLE'}
function ratingCell(source){if(!source?.eligible||source.rank==null)return '<span class="rating-missing">—</span>';const value=source.value==null?'':`<strong>${Number(source.value).toFixed(1)}</strong>`;return `${value}<small>#${source.rank}</small>`}
function ratingHealth(){return DATA.ratings.health.map(x=>`<div class="rating-health-card ${x.composite_eligible?'current':''}"><b>${esc(x.display_name)}</b><strong>${ratingStatus(x.data_freshness_status)}</strong><span>${x.row_count} teams</span><span>Checked ${fmtEt(x.last_checked)}</span>${x.last_data_update?`<span>Source ${fmtEt(x.last_data_update)}</span>`:''}</div>`).join('')}
function ratingSortValue(row,key){if(key==='team')return row.team.toLowerCase();if(key==='average_source_rank'||key==='composite_rank')return row[key]??99999;return row.sources[key]?.rank??99999}
function renderRatingsTable(){const search=$('#ratingsSearch').value.trim().toLowerCase(),conference=$('#ratingsConference').value;let rows=DATA.ratings.teams.filter(x=>(!search||x.team.toLowerCase().includes(search)||x.display_name.toLowerCase().includes(search))&&(!conference||x.conference_id===conference));rows.sort((a,b)=>{const av=ratingSortValue(a,ratingsSort.key),bv=ratingSortValue(b,ratingsSort.key);return ratingsSort.direction*(typeof av==='string'?av.localeCompare(bv):av-bv)||a.team.localeCompare(b.team)});$('#ratingsCount').textContent=`${rows.length} / ${DATA.ratings.teams.length} TEAMS`;$('#ratingsBody').innerHTML=rows.map(x=>`<tr><td class="sticky-composite"><b class="composite-rank">#${x.composite_rank??'—'}</b></td><td class="sticky-team"><strong>${esc(x.team)}</strong></td><td>${esc(x.conference||'—')}</td><td>${x.average_source_rank==null?'—':x.average_source_rank.toFixed(1)}</td>${ratingColumns.map(id=>`<td class="source-rating">${ratingCell(x.sources[id])}</td>`).join('')}</tr>`).join('');}
function closeRatingsDetail(){const p=$('#ratingsDetail');if(p){p.hidden=true;p.innerHTML=''}ratingsDetailTrigger?.setAttribute('aria-expanded','false');ratingsDetailTrigger=null}
function openRatingsDetail(trigger,domain,rows,consensus){if(ratingsDetailTrigger===trigger)return closeRatingsDetail();closeRatingsDetail();ratingsDetailTrigger=trigger;trigger.setAttribute('aria-expanded','true');const p=$('#ratingsDetail');p.innerHTML=`<div class="calculator-detail">${rows.map(x=>`<div><b>${x.name}</b><span>${x.weight}</span><strong>${x.value}</strong></div>`).join('')}<div class="calculator-consensus"><b>CONSENSUS</b><strong>${consensus}</strong></div></div>`;p.hidden=false;const r=trigger.getBoundingClientRect(),w=p.offsetWidth;p.style.left=Math.max(8,Math.min(r.left,innerWidth-w-8))+'px';p.style.top=Math.max(8,Math.min(r.bottom+6,innerHeight-p.offsetHeight-8))+'px'}
function calculatorPrediction(){const visitor=$('#visitorTeam').value,home=$('#homeTeam').value,neutral=$('#neutralSite').checked,out=$('#calculatorResults'),c=DATA.ratings.calculator;if(!visitor||!home||visitor===home){out.innerHTML='<div class="calculator-empty">Choose two different teams.</div>';return}const k=c.kenpom||{},a=k[visitor],h=k[home],avgO=c.national_average_adj_o,avgT=c.national_average_adj_t,tr=c.teamrankings||{},ta=tr[visitor],th=tr[home],spreadRows=[];let total=null;if(a&&h&&avgO!=null&&avgT!=null){const hca=neutral?0:c.home_court_points,neutralMargin=(h.adjusted_efficiency_margin-a.adjusted_efficiency_margin)/100*((h.adjusted_tempo+a.adjusted_tempo)/2);spreadRows.push({name:'KenPom',margin:neutralMargin+hca,hca});const poss=a.adjusted_tempo+h.adjusted_tempo-avgT,awayEff=a.adjusted_offensive_efficiency+h.adjusted_defensive_efficiency-avgO,homeEff=h.adjusted_offensive_efficiency+a.adjusted_defensive_efficiency-avgO;total=(awayEff+homeEff)*poss/100}if(ta&&th&&Number.isFinite(Number(ta.predictive_rating))&&Number.isFinite(Number(th.predictive_rating))&&Number.isFinite(Number(c.teamrankings_home_court_points))){const hca=neutral?0:Number(c.teamrankings_home_court_points);spreadRows.push({name:'TeamRankings',margin:Number(th.predictive_rating)-Number(ta.predictive_rating)+hca,hca})}const margin=spreadRows.length?spreadRows.reduce((s,x)=>s+x.margin,0)/spreadRows.length:null,homeTeam=DATA.ratings.teams.find(x=>x.team_id===home),awayTeam=DATA.ratings.teams.find(x=>x.team_id===visitor);if(margin==null&&total==null){out.innerHTML='<div class="result-box"><small>PREDICTED SPREAD</small><b>—</b></div><div class="result-box"><small>PREDICTED TOTAL</small><b>—</b></div><div class="result-box"><small>PROJECTED SCORE</small><b>—</b></div>';return}const fav=margin==null?null:(margin>=0?homeTeam:awayTeam),spread=fav?`${fav.team} -${Math.abs(margin).toFixed(1)}`:'—',awayScore=total!=null&&margin!=null?(total-margin)/2:null,homeScore=total!=null&&margin!=null?(total+margin)/2:null,weight=spreadRows.length?Math.round(100/spreadRows.length)+'%':'—';out.innerHTML=`<button class="result-box" id="spreadResult"><small>PREDICTED SPREAD</small><b>${esc(spread)}</b></button><button class="result-box" id="totalResult"><small>PREDICTED TOTAL</small><b>${total==null?'—':total.toFixed(1)}</b></button><div class="result-box score"><small>PROJECTED SCORE</small><b>${awayScore==null?'—':esc(awayTeam.team)+' '+awayScore.toFixed(1)}</b><b>${homeScore==null?'—':esc(homeTeam.team)+' '+homeScore.toFixed(1)}</b></div><div class="calculator-site">${neutral?'NEUTRAL · HCA 0.0':'SOURCE-SPECIFIC HOME COURT'}</div>`;$('#spreadResult').onclick=e=>openRatingsDetail(e.currentTarget,'spread',spreadRows.map(x=>({name:x.name,weight,value:`${x.margin>=0?homeTeam.team:awayTeam.team} -${Math.abs(x.margin).toFixed(1)} · HCA ${x.hca.toFixed(1)}`})),spread);$('#totalResult').onclick=e=>openRatingsDetail(e.currentTarget,'total',total==null?[]:[{name:'KenPom',weight:'100%',value:total.toFixed(1)}],total==null?'—':total.toFixed(1))}
function renderRatingsPage(){const root=$('#app'),teams=[...DATA.ratings.teams].sort((a,b)=>a.team.localeCompare(b.team)),conferences=[...new Map(teams.map(x=>[x.conference_id,x.conference])).entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1])));root.className='ratings-dashboard';root.innerHTML=`<section class="ratings-health"><div class="section-title"><b>SOURCE HEALTH</b><span>Last checked and source-update timestamps are distinct.</span></div><div class="rating-health-grid">${ratingHealth()}</div></section><section class="matchup-calculator"><div class="section-title"><b>RATINGS-BASED MATCHUP ESTIMATE</b><span>Spread: KenPom + TeamRankings · Total: KenPom</span></div><div class="calculator-grid"><label>VISITOR TEAM<select id="visitorTeam"><option value="">Select visitor…</option>${teams.map(x=>`<option value="${x.team_id}">${esc(x.team)}</option>`).join('')}</select></label><label>HOME TEAM<select id="homeTeam"><option value="">Select home…</option>${teams.map(x=>`<option value="${x.team_id}">${esc(x.team)}</option>`).join('')}</select></label><label class="neutral-toggle"><input id="neutralSite" type="checkbox"> NEUTRAL SITE</label><div id="calculatorResults" class="calculator-results"><div class="calculator-empty">Choose visitor and home teams.</div></div></div></section><section class="ratings-table-panel"><div class="ratings-controls"><input id="ratingsSearch" placeholder="Find a team"><select id="ratingsConference"><option value="">All conferences</option>${conferences.map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('')}</select><span id="ratingsCount"></span></div><div class="ratings-table-scroll"><table class="consolidated-ratings"><thead><tr>${[['composite_rank','COMPOSITE'],['team','TEAM'],['conference','CONF'],['average_source_rank','AVG RANK'],...ratingColumns.map(id=>[id,names[id].toUpperCase()])].map(([key,label])=>`<th><button data-rating-sort="${key}">${label}</button></th>`).join('')}</tr></thead><tbody id="ratingsBody"></tbody></table></div></section><div id="ratingsDetail" class="ratings-detail" hidden></div>`;$('#ratingsSearch').oninput=renderRatingsTable;$('#ratingsConference').onchange=renderRatingsTable;['#visitorTeam','#homeTeam','#neutralSite'].forEach(s=>$(s).onchange=()=>{const other=s==='#visitorTeam'?'#homeTeam':s==='#homeTeam'?'#visitorTeam':null;if(other&&$(s).value===$(other).value)$(other).value='';closeRatingsDetail();calculatorPrediction()});root.querySelectorAll('[data-rating-sort]').forEach(b=>b.onclick=()=>{const key=b.dataset.ratingSort;ratingsSort.direction=ratingsSort.key===key?-ratingsSort.direction:1;ratingsSort.key=key;renderRatingsTable()});document.addEventListener('pointerdown',e=>{if(ratingsDetailTrigger&&!e.target.closest('.ratings-detail,#spreadResult,#totalResult'))closeRatingsDetail()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeRatingsDetail()});renderRatingsTable()}
